      "b2b.hero.cta1": "Get a fixed quote →",
      "b2b.hero.cta2": "How it works",
      "b2b.trust.eyebrow": "YOUR DATA STAYS YOURS",
      "b2b.trust.title": "Compute without exposure.",
      "b2b.trust.1t": "End-to-end encrypted",
      "b2b.trust.1d": "Jobs and messages are encrypted end to end. Only your nodes can read them.",
      "b2b.trust.2t": "Private by design",
      "b2b.trust.2d": "Inference runs on local LLMs on dedicated nodes. No big-cloud AI ever touches your data.",
      "b2b.trust.3t": "Sovereign & unstoppable",
      "b2b.trust.3d": "A decentralized mesh of independent nodes. No single provider, no lock-in, no cut-off.",
      "b2b.trust.4t": "Fixed, regulated pricing",
      "b2b.trust.4d": "Lock a fixed quote and pay in EUR, USD or USDT — fully invoiced, fully official.",
      "b2b.build.eyebrow": "BUILT FOR BUILDERS",
      "b2b.build.title": "Run what your product needs.",
      "b2b.build.1t": "Your own models",
      "b2b.build.1d": "Bring a custom LLM or pick per job. Mount private datasets or pull from Hugging Face — the network runs it where you say it runs.",
      "b2b.build.2t": "Agents & skills",
      "b2b.build.2d": "Deploy skills and agents on-chain, wire in your tools via MCP, and let the fastest node answer every call.",
      "b2b.build.3t": "One simple API",
      "b2b.build.3d": "Everything is one HTTP API — jobs, chat, search, payments. Integrate in an afternoon.",
      "b2b.build.3cta": "Read the API docs →",
      "b2b.build.4t": "Pay per token",
      "b2b.build.4d": "Metered per AI compute token with a hard budget per job. Unused budget is refunded — no idle GPUs on your bill.",
      "b2b.how.eyebrow": "HOW IT WORKS",
      "b2b.how.title": "From job to result, encrypted.",
      "b2b.how.1t": "Post a job",
      "b2b.how.1d": "Send an encrypted job with a budget through the wallet API.",
      "b2b.how.2t": "The network computes",
      "b2b.how.2d": "The fastest qualified node runs it — on your model, at your budget.",
      "b2b.how.3t": "Verified result",
      "b2b.how.3d": "Work is verified on-chain and unused budget comes back to you.",
      "b2b.ent.eyebrow": "ENTERPRISE",
      "b2b.ent.title": "Need scale<br><span class=\"neon\">or an SLA?</span>",
      "b2b.ent.desc": "Dedicated capacity, private clusters and volume pricing for production workloads. You pay in EUR, USD or USDT — officially and fully invoiced — while the community powering the network is paid in local stablecoins.",
      "b2b.ent.cta": "Talk to us — get a fixed quote →",
      "b2b.ent.cta2": "Explore the network →",
