      "b2b.ent.eyebrow": "საწარმო",
      "b2b.ent.title": "გჭირდება მასშტაბი<br><span class=\"neon\">ან SLA?</span>",
      "b2b.ent.desc": "გამოყოფილი სიმძლავრე, პრივატული კლასტერები და მოცულობითი ფასები საწარმოო დატვირთვებისთვის. შენ იხდი EUR-ში, USD-ში ან USDT-ში — ოფიციალურად, სრული ინვოისით — ხოლო ქსელის მომუშავე საზოგადოება ადგილობრივ სტეიბლქოინებში იღებს ანაზღაურებას.",
