      "b2b.build.1d": "Բեր քո LLM-ը կամ ընտրիր ամեն առաջադրանքի համար։ Միացրու մասնավոր տվյալներ կամ Hugging Face — ցանցը կաշխատեցնի այնտեղ, որտեղ դու կասես։",
