      "b2b.trust.eyebrow": "МААЛЫМАТЫҢ ӨЗҮҢДҮКҮ БОЙДОН КАЛАТ",
      "b2b.trust.title": "Ачыкка чыкпаган эсептөө.",
      "b2b.trust.1t": "Учтан-учка шифрленген",
      "b2b.trust.1d": "Тапшырмалар менен билдирүүлөр учтан-учка шифрленет. Аларды сенин түйүндөрүң гана окуйт.",
      "b2b.trust.2t": "Дизайны боюнча жеке",
      "b2b.trust.2d": "Инференс атайын түйүндөрдө локалдык LLM менен иштейт. Чоң булут AI сенин маалыматыңа эч качан тийбейт.",
      "b2b.trust.3t": "Эгемен жана токтотулгус",
      "b2b.trust.3d": "Көз карандысыз түйүндөрдүн борборсуздандырылган тармагы. Бир да провайдер жок, көз карандылык жок, өчүрүү жок.",
      "b2b.trust.4t": "Туруктуу, жөнгө салынган баа",
      "b2b.trust.4d": "Баа бекитип, EUR, USD же USDT менен төлө — толук эсеп-фактура менен, толук расмий.",
      "b2b.build.eyebrow": "КУРУУЧУЛАР ҮЧҮН",
      "b2b.build.title": "Продуктуңа эмне керек болсо, ошону иштет.",
      "b2b.build.1t": "Өз моделдериң",
      "b2b.build.1d": "Өз LLM-иңди алып кел же ар тапшырмага тандап ал. Жеке датасеттерди же Hugging Face-ти кош — тармак сен айткан жерде иштетет.",
      "b2b.build.2t": "Агенттер жана жөндөмдөр",
      "b2b.build.2d": "Жөндөмдөр менен агенттерди блокчейнге жайгаштыр, куралдарыңды MCP аркылуу кош — ар бир чакырыкка эң тез түйүн жооп берет.",
      "b2b.build.3t": "Бир жөнөкөй API",
      "b2b.build.3d": "Баары бир HTTP API — тапшырмалар, чат, издөө, төлөмдөр. Бир түштөн кийин эле интеграциялайсың.",
      "b2b.build.3cta": "API документтерин оку →",
      "b2b.build.4t": "Токен менен төлө",
      "b2b.build.4d": "AI эсептөө токени менен ченелет, ар тапшырмага катуу бюджет. Колдонулбаган бюджет кайтарылат — эсебиңде бош GPU жок.",
      "b2b.how.eyebrow": "КАНТИП ИШТЕЙТ",
      "b2b.how.title": "Тапшырмадан жыйынтыкка чейин — шифрленген.",
      "b2b.how.1t": "Тапшырма жайгаштыр",
      "b2b.how.1d": "Капчык API аркылуу бюджети бар шифрленген тапшырма жөнөт.",
      "b2b.how.2t": "Тармак эсептейт",
      "b2b.how.2d": "Эң тез ылайыктуу түйүн иштетет — сенин моделиңде, сенин бюджетиңде.",
      "b2b.how.3t": "Текшерилген жыйынтык",
      "b2b.how.3d": "Иш блокчейнде текшерилет, колдонулбаган бюджет өзүңө кайтат.",
      "b2b.ent.eyebrow": "ИШКАНА",
      "b2b.ent.title": "Масштаб керекпи<br><span class=\"neon\">же SLA?</span>",
      "b2b.ent.desc": "Өндүрүштүк жүктөмдөр үчүн атайын кубаттуулук, жеке кластерлер жана көлөмдүк баалар. Сен EUR, USD же USDT менен төлөйсүң — расмий, толук эсеп-фактура менен — ал эми тармакты иштеткен коомчулук жергиликтүү стейблкоиндер менен акы алат.",
      "b2b.ent.cta": "Бизге кайрыл — туруктуу баа ал →",
      "b2b.ent.cta2": "Тармак менен таанышып чык →",
      "doc.nav.upgrade": "Жаңыртуу колдонмосу",
