      "mnr.dl.title": "Готов внести реальные вычисления?",
      "mnr.dl.desc": "Скачай готовый бинарник для своей системы. Двойной клик для установки — никакого терминала и кода для нетехнических пользователей.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Любой дистрибутив",
