      "mnr.net.desc": "Des nœuds exécutant des LLM locaux forment un réseau de calcul IA décentralisé. Quand des tâches arrivent, votre machine les traite et gagne — sans data center.",
      "mnr.app.eyebrow": "L'APPLICATION DE BUREAU",
      "mnr.app.desc": "Une seule app native. Votre nœud rejoint le réseau, votre LLM local résout les tâches IA entrantes, et vous gagnez du POH à chaque fois.",
      "mnr.dl.title": "Prêt à fournir du vrai calcul ?",
      "mnr.dl.desc": "Téléchargez le binaire préconstruit pour votre système. Double-cliquez pour installer — ni terminal ni code pour les utilisateurs non techniques.",
      "mnr.dl.linux.os": "Ubuntu • Debian • Fedora • Toute distro",
      "mnr.dl.linux.desc": "AppImage portable — un seul fichier, tourne sur toute distro. Télécharger → chmod +x → double-cliquer ou lancer depuis n'importe où. Aucune installation root.",
      "mnr.dl.linux.btn1": "Télécharger AppImage (x64)",
      "mnr.dl.linux.btn2": "Télécharger AppImage (ARM64)",
      "mnr.dl.mac.desc": "Ouvrez le .dmg → glissez vers Applications • un « Open Anyway » dans Security & Privacy peut être nécessaire",
      "mnr.dl.mac.btn1": "Télécharger le .dmg Apple Silicon",
      "mnr.dl.mac.btn2": "Télécharger l'installateur .dmg Intel",
      "mnr.dl.win.desc": "Installateur .exe standard avec raccourcis, entrée dans le menu Démarrer et désinstallateur propre. Conçu avec NSIS.",
      "mnr.dl.win.btn": "Télécharger l'installateur Windows",
