      "b2b.trust.eyebrow": "TUS DATOS SIGUEN SIENDO TUYOS",
      "b2b.trust.title": "Cómputo sin exposición.",
      "b2b.trust.1t": "Cifrado de extremo a extremo",
      "b2b.trust.1d": "Las tareas y los mensajes van cifrados de extremo a extremo. Solo tus nodos pueden leerlos.",
      "b2b.trust.2t": "Privado por diseño",
      "b2b.trust.2d": "La inferencia corre en LLM locales sobre nodos dedicados. Ninguna IA de la gran nube toca jamás tus datos.",
